#include "mini_regex.h"
/* Supported: ^ $ . escaped literals, *, +, ?. UTF-8 is matched bytewise.
   Execution budget prevents pathological patterns from running forever. */
static int atom(const char *p,unsigned char c,size_t *used){if(!*p)return 0;if(*p=='\\'&&p[1]){*used=2;return (unsigned char)p[1]==c;}*used=1;return *p=='.'||(unsigned char)*p==c;}
static int match(const char *p,const char *s,size_t n,size_t *end,unsigned long *budget,unsigned int depth){size_t a=1,i,max;char q;if(!(*budget)||depth>128)return 0;--*budget;if(!*p){*end=0;return 1;}if(*p=='$'&&!p[1]){if(n==0){*end=0;return 1;}return 0;}if(*p=='\\'&&p[1])a=2;q=p[a];if(q=='*'||q=='+'||q=='?'){max=0;while(max<n&&atom(p,(unsigned char)s[max],&i)&&i==a&&max<100000)max++;if(q=='?'&&max>1)max=1;for(i=max+1;i>0;i--){size_t take=i-1,rest;if(q=='+'&&take==0)break;if(match(p+a+1,s+take,n-take,&rest,budget,depth+1)){*end=take+rest;return 1;}}return 0;}if(n&&atom(p,(unsigned char)*s,&i)&&i==a){size_t rest;if(match(p+a,s+1,n-1,&rest,budget,depth+1)){*end=rest+1;return 1;}}return 0;}
int fvm_mini_regex_search(const char *p,const char *s,size_t n,size_t *start,size_t *length){size_t i,end;unsigned long budget=1000000UL;if(!p||(!s&&n)||!start||!length)return -1;if(*p=='^'){if(match(p+1,s,n,&end,&budget,0)){*start=0;*length=end;return 1;}return 0;}for(i=0;i<=n;i++){if(match(p,s+i,n-i,&end,&budget,0)){*start=i;*length=end;return 1;}if(!budget)return -2;}return 0;}
